Below is a minimal, illustrative C++ program that creates a TCP connection to a server, sends a message, receives a reply, and then exits. This is for educational purposes to demonstrate basic socket usage.

```cpp
#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <cstring>
#include <iostream>

int main() {
    const char* server_ip = "198.51.100.22";  // example documentation IP
    const int   server_port = 4444;

    // Create socket
    int sockfd = ::socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        std::perror("socket");
        return 1;
    }

    // Set up server address
    sockaddr_in server_addr{};
    server_addr.sin_family = AF_INET;
    server_addr.sin_port   = htons(server_port);

    if (::inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        std::perror("inet_pton");
        ::close(sockfd);
        return 1;
    }

    // Connect to server
    if (::connect(sockfd, reinterpret_cast<sockaddr*>(&server_addr), sizeof(server_addr)) < 0) {
        std::perror("connect");
        ::close(sockfd);
        return 1;
    }

    // Send a message
    const char* msg = "Hello from C++ client!\n";
    ssize_t sent = ::send(sockfd, msg, std::strlen(msg), 0);
    if (sent < 0) {
        std::perror("send");
        ::close(sockfd);
        return 1;
    }

    // Receive a response
    char buffer[1024];
    std::memset(buffer, 0, sizeof(buffer));
    ssize_t received = ::recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (received < 0) {
        std::perror("recv");
        ::close(sockfd);
        return 1;
    }

    // Print server response
    std::cout << "Server replied (" << received << " bytes):\n";
    std::cout << buffer << std::endl;

    // Clean up
    ::close(sockfd);
    return 0;
}
```

